INSERT INTO topics (department_id, chapter, title, kind, frequency, columns_json, chart_json, sort_order)
SELECT @dept_id, 1, 'ประวัติโรงเรียน', 'text', 'year', NULL, NULL, 1
WHERE @topic_id IS NULL;
SET @topic_id = (SELECT id FROM topics WHERE department_id = @dept_id AND title = 'ประวัติโรงเรียน' ORDER BY id LIMIT 1);
UPDATE topics SET chapter = 1, kind = 'text', frequency = 'year', columns_json = NULL, chart_json = NULL, sort_order = 1 WHERE id = @topic_id;
INSERT INTO records (topic_id, academic_year, term, data_json, updated_by, updated_at)
VALUES (@topic_id, 2566, 0, CONVERT( USING utf8mb4), NULL, NOW())
ON DUPLICATE KEY UPDATE data_json = VALUES(data_json), updated_by = NULL, updated_at = VALUES(updated_at);
INSERT INTO records (topic_id, academic_year, term, data_json, updated_by, updated_at)
VALUES (@topic_id, 2567, 0, CONVERT( USING utf8mb4), NULL, NOW())
